Rules.InvariantScript:
Set(
    currentUserID,
    LookUp(
        Users,
        Email = Lower(InputEmail.Text) &&
        Password = InputPassword.Text,
        ID
    )
);

Set(
    usertypeevalue,
    LookUp(
        Users,
        (Email) = Lower(InputEmail.Text) &&
        (Password = InputPassword.Text),
        UserType.Value
    )
);

If(
    IsBlank(usertypeevalue),
    Notify("Incorrect email or password"); Set(labeltxt, true),
    Switch(
        usertypeevalue,
        "Volunteer",
            Navigate(VolunteerDashboard),
        "Duty Officer",
            Navigate(VolunteerDashboard)
    )
);

Reset(InputEmail);
Reset(InputPassword);

